class Header{constructor(){this.systemStatus={online:true,uptime:'15d 4h 23m',lastUpdate:new Date()};this.notifications=[];this.authService=null;this.currentUser=null;this.init();this.loadTheme();this.initAuth();}init(){this.render();this.attachEventListeners();this.startStatusUpdates();this.loadNotifications();}render(){const headerContainer=document.querySelector('.top-header')|| this.createHeaderContainer();headerContainer.innerHTML=this.getTemplate();this.updateThemeButton();setTimeout(()=>{this.attachLogoutListener();},10);}createHeaderContainer(){const header=document.createElement('header');header.className='top-header';const mainContent=document.querySelector('.main-content');if(mainContent){mainContent.insertBefore(header,mainContent.firstChild);}return header;}getTemplate(){return ` <div class="header-left"> <button class="mobile-menu-btn" id="mobile-menu-btn" title="Menu"> <i class="fas fa-bars"></i> </button> </div> <div class="header-right"> <div class="system-status"> <span class="status-indicator ${this.systemStatus.online ? 'online':'offline'}"></span> <span>System ${this.systemStatus.online ? 'Online':'Offline'}</span> <span class="uptime">Uptime:${this.systemStatus.uptime}</span> <span class="last-update">Last Update:<span id="last-update-time">${this.formatTime(this.systemStatus.lastUpdate)}</span></span> </div> <div class="header-actions"> <button class="header-btn" id="refresh-btn" title="Refresh Data"> <i class="fas fa-sync-alt"></i> </button> <div class="notification-menu"> <button class="header-btn" id="notifications-btn" title="Notifications"> <i class="fas fa-bell"></i> ${this.notifications.length > 0 ? '<span class="notification-dot"></span>':''}</button> <div class="notification-dropdown" id="notification-dropdown"> <div class="notification-header"> <h4>Notifications</h4> <button class="mark-all-read" id="mark-all-read">Mark all read</button> </div> <div class="notification-list" id="notification-list"> ${this.renderNotifications()}</div> <div class="notification-footer"> <a href="#alerts" class="view-all-notifications">View all alerts</a> </div> </div> </div> <button class="header-btn" id="dark-mode-toggle" title="Toggle Theme"> <i class="fas fa-moon"></i> </button> <button class="header-btn" id="fullscreen-btn" title="Fullscreen"> <i class="fas fa-expand"></i> </button> <div class="user-menu"> <button class="header-btn user-avatar" title="${this.getUserDisplayName()}"> <i class="fas fa-user"></i> <span class="user-name">${this.getUserDisplayName()}</span> </button> <div class="user-dropdown"> <div class="user-info"> <div class="user-details"> <strong>${this.getUserDisplayName()}</strong> <small>${this.getUserRole()}</small> </div> </div> <hr> <a href="#profile" onclick="event.preventDefault();alert('Profile settings coming soon!')"><i class="fas fa-user-circle"></i> Profile</a> <a href="#preferences" onclick="event.preventDefault();alert('Preferences coming soon!')"><i class="fas fa-cog"></i> Preferences</a> <hr> <a href="#" id="logout-btn"><i class="fas fa-sign-out-alt"></i> Logout</a> </div> </div> </div> </div> `;}renderNotifications(){if(this.notifications.length===0){return '<div class="no-notifications">No new notifications</div>';}return this.notifications.map(notification=> ` <div class="notification-item ${notification.read ? 'read':'unread'}" data-id="${notification.id}"> <div class="notification-icon ${notification.type}"> <i class="fas ${this.getNotificationIcon(notification.type)}"></i> </div> <div class="notification-content"> <div class="notification-title">${notification.title}</div> <div class="notification-message">${notification.message}</div> <div class="notification-time">${this.getRelativeTime(notification.timestamp)}</div> </div> <button class="notification-dismiss" data-id="${notification.id}"> <i class="fas fa-times"></i> </button> </div> `).join('');}attachEventListeners(){document.addEventListener('click',(e)=>{if(e.target.id==='mobile-menu-btn' || e.target.closest('#mobile-menu-btn')){this.toggleMobileMenu();}});const sidebarToggle=document.querySelector('.sidebar-toggle');if(sidebarToggle){sidebarToggle.addEventListener('click',()=> this.toggleSidebar());}const refreshBtn=document.getElementById('refresh-btn');if(refreshBtn){refreshBtn.addEventListener('click',()=> this.refreshData());}const notificationsBtn=document.getElementById('notifications-btn');if(notificationsBtn){notificationsBtn.addEventListener('click',()=> this.toggleNotifications());}const markAllRead=document.getElementById('mark-all-read');if(markAllRead){markAllRead.addEventListener('click',()=> this.markAllNotificationsRead());}const themeToggle=document.getElementById('dark-mode-toggle');if(themeToggle){themeToggle.addEventListener('click',()=> this.toggleDarkMode());}const fullscreenBtn=document.getElementById('fullscreen-btn');if(fullscreenBtn){fullscreenBtn.addEventListener('click',()=> this.toggleFullscreen());}document.addEventListener('click',(e)=>{const userAvatarButton=e.target.closest('.user-avatar');if(userAvatarButton){e.preventDefault();e.stopPropagation();this.toggleUserMenu();return;}});this.attachLogoutListener();document.addEventListener('click',(e)=> this.closeDropdowns(e));}attachLogoutListener(retryCount=0){const maxRetries=10;const logoutBtn=document.getElementById('logout-btn');if(logoutBtn && !logoutBtn.hasAttribute('data-logout-attached')){logoutBtn.setAttribute('data-logout-attached','true');logoutBtn.addEventListener('click',(e)=>{e.preventDefault();e.stopPropagation();console.log('Logout button clicked!');this.handleLogoutClick();});console.log('✅ Logout event listener attached successfully');return true;}if(!logoutBtn && retryCount < maxRetries){setTimeout(()=>{this.attachLogoutListener(retryCount+1);},100);return false;}if(!logoutBtn){console.error('❌ Logout button not found after maximum retries');}return !!logoutBtn;}async handleLogoutClick(){console.log('🚪 Logout process initiated');const shouldLogout=await this.showLogoutConfirmation();if(!shouldLogout){console.log('❌ Logout cancelled by user');return;}this.setLogoutLoading(true);try{console.log('🔄 Processing logout...');if(this.authService){await this.authService.logout();}else{await this.fallbackLogout();}console.log('✅ Logout completed successfully');}catch(error){console.error('❌ Logout error:',error);this.showLogoutError(error);}finally{this.setLogoutLoading(false);}}async showLogoutConfirmation(){return new Promise((resolve)=>{const result=confirm('Are you sure you want to logout?');resolve(result);});}setLogoutLoading(loading){const logoutBtn=document.getElementById('logout-btn');if(logoutBtn){if(loading){logoutBtn.innerHTML='<i class="fas fa-spinner fa-spin"></i> Logging out...';logoutBtn.style.opacity='0.7';logoutBtn.disabled=true;}else{logoutBtn.innerHTML='<i class="fas fa-sign-out-alt"></i> Logout';logoutBtn.style.opacity='1';logoutBtn.disabled=false;}}}async fallbackLogout(){console.log('🔄 Using fallback logout...');this.clearAllAuthData();this.showLogoutToast();await new Promise(resolve=> setTimeout(resolve,1000));const baseUrl=window.location.origin;const loginUrl=baseUrl+'/login.html';window.location.replace(loginUrl);}clearAllAuthData(){const keysToRemove=[ 'lpr_auth_token','user-session','auth-token','access_token','refresh_token','user_data','auth_state' ];keysToRemove.forEach(key=>{localStorage.removeItem(key);sessionStorage.removeItem(key);});console.log('🧹 All authentication data cleared');}showLogoutError(error){const toast=document.createElement('div');toast.className='toast toast-error';toast.innerHTML=` <i class="fas fa-exclamation-triangle"></i> <span>Logout failed. Please try again.</span> `;this.showToast(toast);}toggleSidebar(){if(window.sidebar && window.sidebar.toggleCollapse){window.sidebar.toggleCollapse();}else{const appLayout=document.querySelector('.app-layout');if(appLayout){const isExpanded=appLayout.getAttribute('data-nav-expanded')==='true';appLayout.setAttribute('data-nav-expanded',(!isExpanded).toString());localStorage.setItem('sidebar-collapsed',isExpanded.toString());}}}toggleMobileMenu(){const appLayout=document.querySelector('.app-layout');const overlay=document.querySelector('.mobile-sidebar-overlay');if(appLayout){const isExpanded=appLayout.getAttribute('data-nav-expanded')==='true';appLayout.setAttribute('data-nav-expanded',(!isExpanded).toString());if(!isExpanded && overlay){overlay.onclick=()=>{appLayout.setAttribute('data-nav-expanded','false');};}}}refreshData(){console.log('Refreshing data...');const refreshBtn=document.getElementById('refresh-btn');if(!refreshBtn){console.error('Refresh button not found');return;}const icon=refreshBtn.querySelector('i');icon.classList.add('fa-spin');refreshBtn.disabled=true;setTimeout(()=>{icon.classList.remove('fa-spin');refreshBtn.disabled=false;this.updateSystemStatus();this.showToast('Data refreshed successfully','success');},1500);window.dispatchEvent(new CustomEvent('dataRefresh'));}toggleNotifications(){const dropdown=document.getElementById('notification-dropdown');if(dropdown){dropdown.classList.toggle('show');}}markAllNotificationsRead(){this.notifications=this.notifications.map(n=>({...n,read:true}));this.updateNotificationBadge();this.render();}toggleDarkMode(){const currentTheme=document.documentElement.getAttribute('data-theme');console.log('Toggling dark mode,current theme:',currentTheme);if(currentTheme==='dark'){this.enableLightMode();}else{this.enableDarkMode();}}enableDarkMode(){document.documentElement.setAttribute('data-theme','dark');localStorage.setItem('theme','dark');this.updateThemeButton();}enableLightMode(){document.documentElement.setAttribute('data-theme','light');localStorage.setItem('theme','light');this.updateThemeButton();}updateThemeButton(){const darkModeToggle=document.getElementById('dark-mode-toggle');if(darkModeToggle){const icon=darkModeToggle.querySelector('i');const currentTheme=document.documentElement.getAttribute('data-theme');if(icon){if(currentTheme==='dark'){icon.className='fas fa-sun';darkModeToggle.title='Switch to Light Mode';}else{icon.className='fas fa-moon';darkModeToggle.title='Switch to Dark Mode';}}}}toggleFullscreen(){if(!document.fullscreenElement){document.documentElement.requestFullscreen().catch(err=>{console.error('Failed to enter fullscreen:',err);});const fullscreenBtn=document.getElementById('fullscreen-btn');if(fullscreenBtn){const icon=fullscreenBtn.querySelector('i');if(icon){icon.className='fas fa-compress';}}}else{document.exitFullscreen().catch(err=>{console.error('Failed to exit fullscreen:',err);});const fullscreenBtn=document.getElementById('fullscreen-btn');if(fullscreenBtn){const icon=fullscreenBtn.querySelector('i');if(icon){icon.className='fas fa-expand';}}}}toggleUserMenu(){const dropdown=document.querySelector('.user-dropdown');if(dropdown){dropdown.classList.toggle('show');}}closeDropdowns(e){const notificationDropdown=document.getElementById('notification-dropdown');const notificationBtn=document.getElementById('notifications-btn');if(notificationDropdown && !notificationBtn.contains(e.target)&& !notificationDropdown.contains(e.target)){notificationDropdown.classList.remove('show');}const userDropdown=document.querySelector('.user-dropdown');const userAvatar=document.querySelector('.user-avatar');if(userDropdown && !userAvatar.contains(e.target)&& !userDropdown.contains(e.target)){userDropdown.classList.remove('show');}}startStatusUpdates(){setInterval(()=>{this.systemStatus.lastUpdate=new Date();const timeElement=document.getElementById('last-update-time');if(timeElement){timeElement.textContent=this.formatTime(this.systemStatus.lastUpdate);}},60000);}updateSystemStatus(){this.systemStatus.lastUpdate=new Date();this.systemStatus.online=true;this.render();}loadNotifications(){this.notifications=[{id:1,type:'warning',title:'Camera Offline',message:'Camera 3 at parking lot is not responding',timestamp:new Date(Date.now()-15*60*1000),read:false},{id:2,type:'info',title:'System Update',message:'LPR accuracy improved to 98.5%',timestamp:new Date(Date.now()-2*60*60*1000),read:false}];this.updateNotificationBadge();}updateNotificationBadge(){const unreadCount=this.notifications.filter(n=> !n.read).length;const badge=document.querySelector('.notification-dot');const btn=document.getElementById('notifications-btn');if(unreadCount > 0){if(!badge && btn){btn.innerHTML+='<span class="notification-dot"></span>';}}else{if(badge){badge.remove();}}}getNotificationIcon(type){const icons={warning:'fa-exclamation-triangle',error:'fa-times-circle',info:'fa-info-circle',success:'fa-check-circle'};return icons[type] || 'fa-bell';}formatTime(date){return date.toLocaleTimeString('en-US',{hour12:false,hour:'2-digit',minute:'2-digit'});}getRelativeTime(date){const now=new Date();const diff=now-date;const minutes=Math.floor(diff/60000);if(minutes < 1)return 'Just now';if(minutes < 60)return `${minutes}m ago`;if(minutes < 1440)return `${Math.floor(minutes/60)}h ago`;return `${Math.floor(minutes/1440)}d ago`;}showToast(message,type='info'){const toast=document.createElement('div');toast.className=`toast toast-${type}`;toast.innerHTML=` <i class="fas ${this.getNotificationIcon(type)}"></i> <span>${message}</span> `;const container=document.getElementById('toast-container')|| document.body;container.appendChild(toast);setTimeout(()=>{toast.remove();},3000);}addNotification(notification){this.notifications.unshift({id:Date.now(),timestamp:new Date(),read:false,...notification});this.updateNotificationBadge();this.render();}setSystemStatus(status){this.systemStatus={...this.systemStatus,...status};this.render();}loadTheme(){const savedTheme=localStorage.getItem('theme');const prefersDark=window.matchMedia && window.matchMedia('(prefers-color-scheme:dark)').matches;if(savedTheme==='dark'){this.enableDarkMode();}else if(savedTheme==='light'){this.enableLightMode();}else if(prefersDark){this.enableDarkMode();}else{this.enableLightMode();}}async initAuth(){try{const{default:AuthService}=await import('../../services/AuthService.js');this.authService=new AuthService();const authAvailable=await this.authService.testConnection();if(!authAvailable){console.warn('Authentication endpoints not available,running in anonymous mode');return;}window.addEventListener('userLogin',(e)=> this.onUserLogin(e.detail.user));window.addEventListener('userLogout',()=> this.onUserLogout());if(this.authService.isAuthenticated()){try{this.currentUser=this.authService.getUser();this.render();}catch(error){console.warn('Failed to get current user,clearing invalid token');this.authService.logout();}}}catch(error){console.error('Failed to initialize authentication:',error);}}onUserLogin(user){this.currentUser=user;this.render();this.showToast(`Welcome back,${user.username}!`,'success');}onUserLogout(event){console.log('🔄 Header received logout event:',event?.detail);this.currentUser=null;this.authService=null;this.setLogoutLoading(false);this.render();console.log('✅ Header logout cleanup completed');}showLogoutToast(){const toast=document.createElement('div');toast.className='toast toast-info logout-toast';toast.innerHTML=` <i class="fas fa-sign-out-alt"></i> <span>Logging out...</span> `;let container=document.getElementById('toast-container');if(!container){container=document.createElement('div');container.id='toast-container';container.className='toast-container';document.body.appendChild(container);}container.appendChild(toast);setTimeout(()=>{if(toast.parentElement){toast.remove();}},2000);}getUserDisplayName(){if(this.currentUser){return this.currentUser.username || this.currentUser.email || 'User';}return 'Guest';}getUserRole(){if(this.currentUser){return this.currentUser.role || 'guest';}return 'guest';}setAuthService(authService){this.authService=authService;if(authService && authService.isAuthenticated()){this.currentUser=authService.getUser();this.render();}}}export default Header;